             this.video.playbackRate = Math.max(0.85, 1.0 - Math.abs(errorFactor) * 0.2);
        } else {
             this.video.playbackRate = 1.0;
        }

        this.speedControl.value = Math.max(0.5, Math.min(maxSpeed, targetSpeed));
        this.updateRangeValue('speed');
    }
}
